import json

async def execute(self, inputs):
    from src.runtime.assets.assembly import get_storytelling_layout_engine, EnvironmentPlan

    env_plan_json = str(inputs.get('environment_plan_json') or '')
    if not env_plan_json.strip():
        self.log_error('[StorytellingLayout] environment_plan_json is required.')
        return {'story_layout_json': '{}', 'layout_id': '', 'theme': '', 'hero_zone': '', 'viewer_path_json': '[]', 'visual_flow': '', 'beat_count': 0, 'ok': False, 'exec_out': True}

    try:
        env_dict = json.loads(env_plan_json)
        env_plan = EnvironmentPlan.from_dict(env_dict)

        engine = get_storytelling_layout_engine()
        layout = engine.generate_story_layout(env_plan)

        self.log_info(
            f'[StorytellingLayout] {env_plan.environment!r}: '
            f'theme={layout.theme!r}, {len(layout.beats)} beats, ok={layout.ok}'
        )
        if layout.warnings:
            for w in layout.warnings:
                self.log_warning(f'[StorytellingLayout] {w}')

        return {
            'story_layout_json': json.dumps(layout.to_dict()),
            'layout_id':    layout.layout_id,
            'theme':        layout.theme,
            'hero_zone':    layout.hero_zone,
            'viewer_path_json': json.dumps(layout.viewer_path),
            'visual_flow':  layout.visual_flow,
            'beat_count':   len(layout.beats),
            'ok':           layout.ok,
            'exec_out':     True,
        }
    except Exception as e:
        self.log_error(f'[StorytellingLayout] {e}')
        return {'story_layout_json': '{}', 'layout_id': '', 'theme': '', 'hero_zone': '', 'viewer_path_json': '[]', 'visual_flow': '', 'beat_count': 0, 'ok': False, 'exec_out': True}

def register_node():
    from src.nodes.base import BaseNode
    class Hou_Mcp_Storytelling_Layout(BaseNode):
        name = 'hou_mcp_storytelling_layout'
        async def execute(self, inputs):
            return await execute(self, inputs)
    return Hou_Mcp_Storytelling_Layout
